from genesis.engine.solvers.rigid.stress.surface_inverse import *

@qd.func
def func_original_block(young: float, omega: qd.Tensor, stress_state: StressState, surface_inverse_info: StressSurfaceInverseInfo, block_dim: qd.template()):
    qd.loop_config(block_dim=block_dim)
    for (i_n, i_b) in qd.ndrange(stress_state.rhs.shape[0], stress_state.active.shape[0]):
        w = omega[i_b]
        terms = qd.Vector([w[0] * w[0], w[1] * w[1], w[2] * w[2], w[0] * w[1], w[0] * w[2], w[1] * w[2]])
        value = surface_inverse_info.centrifugal[i_n] @ terms
        for slot in range(stress_state.boundary_count[i_b]):
            j = stress_state.boundary_columns[slot, i_b]
            node = surface_inverse_info.nodes[j]
            value += surface_inverse_info.force_blocks[i_n, j] @ stress_state.force[node, i_b]
        stress_state.displacement[i_n, i_b] = value / young
    for i_b in range(stress_state.active.shape[0]):
        stress_state.active[i_b] = 1
        stress_state.valid[i_b] = True

@qd.func
def func_traversal(young: float, omega: qd.Tensor, stress_state: StressState, surface_inverse_info: StressSurfaceInverseInfo, env_tile: qd.template(), block_dim: qd.template()):
    qd.loop_config(block_dim=block_dim)
    for i_thread in range(stress_state.rhs.shape[0] * ((stress_state.active.shape[0] + env_tile - 1) // env_tile) * env_tile):
        i_index = i_thread // env_tile
        i_n = i_index % stress_state.rhs.shape[0]
        i_b = i_index // stress_state.rhs.shape[0] * env_tile + i_thread % env_tile
        if i_b < stress_state.active.shape[0]:
            w = omega[i_b]
            terms = qd.Vector([w[0] * w[0], w[1] * w[1], w[2] * w[2], w[0] * w[1], w[0] * w[2], w[1] * w[2]])
            value = surface_inverse_info.centrifugal[i_n] @ terms
            for slot in range(stress_state.boundary_count[i_b]):
                j = stress_state.boundary_columns[slot, i_b]
                node = surface_inverse_info.nodes[j]
                value += surface_inverse_info.force_blocks[i_n, j] @ stress_state.force[node, i_b]
            stress_state.displacement[i_n, i_b] = value / young
    for i_b in range(stress_state.active.shape[0]):
        stress_state.active[i_b] = 1
        stress_state.valid[i_b] = True

@qd.kernel(graph=True)
def kernel_traversal(young: float, omega: qd.Tensor, stress_state: StressState, surface_inverse_info: StressSurfaceInverseInfo, env_tile: qd.template(), block_dim: qd.template()):
    func_traversal(young, omega, stress_state, surface_inverse_info, env_tile, block_dim)

@qd.kernel(graph=True)
def kernel_original_block(young: float, omega: qd.Tensor, stress_state: StressState, surface_inverse_info: StressSurfaceInverseInfo, block_dim: qd.template()):
    func_original_block(young, omega, stress_state, surface_inverse_info, block_dim)
